WITH exploded AS (SELECT id, customer_id, created_at, value FROM carts LATERAL VIEW EXPLODE(coupon_codes) li AS value) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, customer_id, MAX(created_at) AS last_seen, COUNT_IF(value = 'WELCOME5') AS welcome5_events, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, MAX(created_at) AS ended_at FROM exploded GROUP BY DATE_TRUNC('DAY', created_at), customer_id HAVING (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 < 1000000;
